"""CPU-only deterministic provenance/reversibility and coverage summary; no labels or NN."""
import pathlib,json,sys,hashlib,collections,statistics,datetime
P=pathlib.Path(__file__).parent;R=P.parent;sys.path.insert(0,str(R))
from anchor_mapping import text_view,original_anchors,canonical_sha
from anchor_mapping_ab import map_clusters_ab,inject_ab
s=json.loads((P/'full48/state.json').read_text());assert s['status']=='complete_input_only_native_census' and s['completed_documents']==48
b=(P/'full48/documents.jsonl').read_bytes();assert hashlib.sha256(b).hexdigest()==s['documents_sha256'];rows=[json.loads(x) for x in b.decode().splitlines()];inputs=[json.loads(x) for x in (P/'input-only48.jsonl').read_text().splitlines()];assert len(rows)==len(inputs)==48
lengths=collections.defaultdict(list);delta=collections.defaultdict(collections.Counter);offset_errors=collections.Counter();recomputed=collections.defaultdict(collections.Counter)
for row,inp in zip(rows,inputs):
 doc=inp['document'];assert row['pmc_id']==str(doc['pmc_id']) and row['group']==inp['group'];text,segments=text_view(doc);modekeys={}
 assert row['native_logit_stats']['finite']
 for mode in ['A','B']:
  old=row['modes'][mode];source=old['mapping']['clusters'][0]['source'] if old['mapping']['clusters'] else {'unused':True}
  m=map_clusters_ab(doc,text,segments,row['clusters_local_char_offsets'],source,mode);derived,side=inject_ab(doc,m);assert m==old['mapping'] and side==old['sidecar']
  for before,after in zip(doc['patient'],derived['patient']):assert after['mention'][:len(before['mention'])]==before['mention'] and after['patient_id']==before['patient_id']
  # Reversible input reconstruction: all additions are external sidecar candidates.
  restored=json.loads(json.dumps(derived))
  for before,after in zip(doc['patient'],restored['patient']):after['mention']=after['mention'][:len(before['mention'])]
  assert restored==doc
  modekeys[mode]={(a['patient_id'],a['mention']['offset'],a['mention']['length']) for a in side['added_mentions']};assert len(modekeys[mode])==len(side['added_mentions'])
  lengths[(row['group'],mode)].extend(a['mention']['length'] for a in side['added_mentions'])
  if mode=='A':
   for c in m['clusters']:
    for e in c['invalid']:offset_errors[e]+=1
 for group in [row['group'],'all48']:
  delta[group].update(A_only=len(modekeys['A']-modekeys['B']),B_only=len(modekeys['B']-modekeys['A']),both=len(modekeys['A']&modekeys['B']))
 recomputed[row['group']].update(row['metrics'])
assert {k:dict(v) for k,v in recomputed.items()}==s['groups']
def stats(v):return {'count':len(v),'min':min(v) if v else None,'median':statistics.median(v) if v else None,'max':max(v) if v else None,'total':sum(v)}
summary={'status':'complete_input_only_coverage_not_quality','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'groups':s['groups'],'added_length_characters':{g:{m:stats(lengths[(g,m)]) for m in ['A','B']} for g in ['train32','F1']},'A_B_addition_set_comparison':{g:dict(c) for g,c in delta.items()},'native_tokens':stats([r['metrics']['native_tokens'] for r in rows]),'characters':stats([r['metrics']['characters'] for r in rows]),'all_original_mentions_preserved_and_reversible':True,'all_numeric_logits_finite':True,'rejected_coordinate_errors':dict(offset_errors),'unique_parameters':s['actual_unique_parameters'],'combined_with_current_production_parameters':9597467990+s['actual_unique_parameters'],'NCR_not_included':True,'full48_seconds':s['seconds'],'probe_seconds':json.loads((P/'probe/state.json').read_text())['seconds'],'GPU':{'device':s['cuda_device_name'],'uuid':s['cuda_device_uuid'],'peak_allocated_bytes':s['cuda_peak_memory_allocated_bytes'],'peak_reserved_bytes':s['cuda_peak_memory_reserved_bytes']},'quality_evaluated':False,'input_to_9B_prompt_or_training':False,'source_and_outputs':{n:{'bytes':(P/n).stat().st_size,'sha256':hashlib.sha256((P/n).read_bytes()).hexdigest()} for n in ['plan.json','gpu-plan.json','input-manifest.json','input-only48.jsonl','full48/state.json','full48/documents.jsonl','full48/documents.jsonl.gz','full48-job.json','summarize_census.py']},'limitations':['Known unique anchor membership is a candidate identity, not validated patient identity or clinical ownership.','B rejects clusters with multiple given patients; unanchored other people can remain ambiguous.','Any anchoring NP that contains an original mention overlaps that mention and is itself excluded from additions.','No gold entities/associations, original dev, quality evaluation, LLM calls, thresholds or full48 retries.','CPU probe and CUDA full48 kernels can differ numerically; no comparison of task quality is implied.']}
(P/'SUMMARY.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Frozen train32 + F1 native coreference input census','',f"Completed all 48 documents once in {s['seconds']:.3f}s on fresh-empty A30 GPU1, inside the 600s cap. The separate first-document CPU probe completed in {summary['probe_seconds']:.3f}s. This report measures unlabeled input coverage only; it does not estimate patient attribution or task quality.",'','| Inputs / mapping | Patients with additions | Docs with additions | New nonoverlapping mentions | Unique-patient clusters | Conflicting clusters |','|---|---:|---:|---:|---:|---:|']
for group in ['train32','F1']:
 d=s['groups'][group]
 for mode in ['A','B']:lines.append('| '+group+' / '+mode+' | '+' | '.join(str(d[mode+'_'+k]) for k in ['patients_with_additions','documents_with_additions','new_nonoverlapping_mentions','unique_patient_clusters','conflicting_patient_clusters'])+' |')
lines+=['',f"All {sum(v['original_mentions'] for v in s['groups'].values())} original mention records for {sum(v['patients'] for v in s['groups'].values())} supplied patient IDs were preserved. Every derived candidate input was reconstructed and reversed locally from its sidecar with exact original input equality. All native logits were finite. Rejected coordinate errors: `{dict(offset_errors)}`.",'','A uses exact original anchor intervals. B uses full containment of given anchors and unions patient IDs over the entire cluster; multiple patients/shared coordinates reject the entire cluster. Both reject cross-passage/separator spans and additions overlapping old anchors or each other. Literal aliases never establish identity. The NP used for B containment itself overlaps an old anchor and is not added. Synthetic A=0 remains preserved; B passed known-multiple-patient NP/shared-coordinate/cross-passage rejection checks.','',f"Addition-set comparison: `{summary['A_B_addition_set_comparison']}`. Added mention character lengths and native length distribution are recorded in SUMMARY.json. These are candidate spans, including ordinary referring expressions; no semantic correctness labels were read or inferred.",'',f"Actual F-coref parameters {s['actual_unique_parameters']:,}; current production plus F-coref = {summary['combined_with_current_production_parameters']:,}. This excludes a prospective NCR addition. Model revision e91dfff12879495d882ba9460d0c5d5dd44ade59 and native source ae224139196d122b225af5a7e73b5fc0b6e1076d stayed fixed; BF16/singleton/maxsegment512/maxdocNone/maxbatch10000, no truncation. GPU allocated peak {s['cuda_peak_memory_allocated_bytes']:,} bytes. CPU/GPU numerical kernels differ, so the CPU probe is timing evidence only.",'','No original-dev data, train/F1 gold entity/association labels, 9B prompt generation, LLM training/inference or quality scoring was used. This output supplies reversible identity candidates only. A unique known anchor cannot rule out unanchored other people in a cluster or establish clinical ownership. Any downstream prompt use requires separately frozen provenance and coverage inspection; task quality remains unknown.','','Detailed native clusters/mapping sidecars remain in external `full48/documents.jsonl` and compressed copy; their SHA/bytes and all source/input references are in SUMMARY.json. The original CPU plan/probe, GPU device-only patch, exact owner backup commit, fresh resource check, actual job/deadline, logs and terminal status remain separately available.']
(P/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'groups':summary['groups'],'A_B':summary['A_B_addition_set_comparison'],'seconds':s['seconds'],'offset_errors':dict(offset_errors)}))
